module multi_pipe_4bit #(
    parameter size = 4,
    parameter N = 2 * size
) (
    input 						clk,
    input 						rst_n,
    input	[size-1:0]			mul_a,
    input	[size-1:0]			mul_b,
    output	reg	[size*2-1:0]	mul_out
);

    wire [7:0] mul_a_ext, mul_b_ext;
    assign mul_a_ext = {4'b0, mul_a};
    assign mul_b_ext = {4'b0, mul_b};

    wire [7:0] partial_products [3:0];
    genvar i;
    generate
        for(i = 0; i < 4; i = i + 1) begin : gen_partial_products
            assign partial_products[i] = (mul_b_ext[i]) ? (mul_a_ext << i) : 'd0;
        end
    endgenerate

    reg [7:0] reg_sum [3:0];
    integer j;
    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            for(j = 0; j < 4; j = j + 1) begin
                reg_sum[j] <= 0;
            end
        end else begin
            for(j = 0; j < 4; j = j + 1) begin
                reg_sum[j] <= reg_sum[j] + partial_products[j];
            end
        end
    end

    reg [7:0] product;
    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            product <= 0;
        end else begin
            product <= reg_sum[0] + reg_sum[1] + reg_sum[2] + reg_sum[3];
        end
    end

    assign mul_out = product;
endmodule

module verified_multi_pipe#(
	parameter size = 4
)(
	input 						clk 		,   
	input 						rst_n		,
	input	[size-1:0]			mul_a		,
	input	[size-1:0]			mul_b		,

 	output	reg	[size*2-1:0]	mul_out		
);

parameter N = 2 * size;

reg     [N-1:0]     sum_tmp1                ;
reg     [N-1:0]     sum_tmp2                ;
wire    [N-1:0]     mul_a_extend            ;
wire    [N-1:0]     mul_b_extend            ;

wire    [N-1:0]     mul_result[size-1:0]    ;

genvar i;
generate
    for(i = 0; i < size; i = i + 1) begin:add
        assign mul_result[i] = mul_b[i] ? mul_a_extend << i : 'd0;
    end
endgenerate

assign mul_a_extend = {{size{1'b0}}, mul_a};
assign mul_b_extend = {{size{1'b0}}, mul_b};

always @(posedge clk or negedge rst_n) begin
    if(!rst_n) begin
        sum_tmp1 <= 'd0;
        sum_tmp2 <= 'd0;
    end
    else begin
        sum_tmp1 <= mul_result[0] + mul_result[1];
        sum_tmp2 <= mul_result[2] + mul_result[3];
    end
end

always @(posedge clk or negedge rst_n) begin
    if(!rst_n) begin
        mul_out <= 'd0;
    end
    else begin
        mul_out <= sum_tmp1 + sum_tmp2;
    end
end

endmodule
